// Брейкпоінти — мінімальна ширина рівня. CSS-змінні в @media не працюють,
// тож стилі пишуть літерал, але stylelint пропускає лише ці значення
// (stylelint.config.mjs читає цей файл), а TS будує запити звідси.
export const BREAKPOINTS = {
    sm: 600, // широкий телефон: сітки карток на 3 колонки
    md: 768, // планшет: від нього — десктопна розкладка з бічною панеллю
    lg: 1024, // ноутбук
    xl: 1200, // широкий екран
};
// «Нижче рівня»: (max-width: 767px) — у тому ж синтаксисі, що й matchMedia
// у старих браузерах.
export const below = (breakpoint) => `(max-width: ${BREAKPOINTS[breakpoint] - 1}px)`;
export const MOBILE_MEDIA_QUERY = below('md');
