import { UP_DOWN_SCHEMES } from './schemes';
export const TONES = {
    neutral: { role: 'neutral' },
    accent: { role: 'brand' },
    success: { family: 'emerald' },
    danger: { family: 'crimson' },
    warning: { family: 'amber' },
    info: { family: 'blue' },
    long: { slot: 'up' },
    short: { slot: 'down' },
    profit: { slot: 'up' },
    loss: { slot: 'down' },
    bull: { slot: 'up' },
    bear: { slot: 'down' },
    takeProfit: { tone: 'profit' },
    stopLoss: { tone: 'loss' },
    trailingStop: { family: 'violet' },
    price: { tone: 'accent' },
    volume: { role: 'volume' },
    entry: { role: 'entry' },
};
export const TONE_NAMES = Object.keys(TONES);
export const EMPHASES = ['strong', 'soft'];
export const isTone = (value) => typeof value === 'string' && Object.prototype.hasOwnProperty.call(TONES, value);
export function resolveTone(tone, scheme) {
    const seen = new Set();
    let current = tone;
    for (;;) {
        if (seen.has(current))
            throw new Error(`Цикл у TONES: ${[...seen].join(' -> ')}`);
        seen.add(current);
        const source = TONES[current];
        if ('family' in source)
            return { family: source.family };
        if ('role' in source)
            return { role: source.role };
        if ('slot' in source)
            return { family: UP_DOWN_SCHEMES[scheme][source.slot] };
        current = source.tone;
    }
}
