import { LS_SELECTED_THEME_KEY } from '06_shared/constants/localStorage';
import { DEFAULT_THEME, isTheme } from '06_shared/contexts/ThemeContext';
// Невідоме значення в localStorage (стара назва теми, ручна правка) дало б
// класу body імʼя без жодного кольорового токена — тому лише відома тема.
export const getThemeFromLS = () => {
    const stored = localStorage.getItem(LS_SELECTED_THEME_KEY);
    return isTheme(stored) ? stored : DEFAULT_THEME;
};
