import cs from '06_shared/styles/common.module.css';
import { groupVar, toneVar } from './cssVars';
// Звʼязка компонента з тоном: класи в common.module.css (.fill, .fillHover,
// .fillPress, .fillCard, .ink), а конкретний тон — інлайн-змінними.
// strong — суцільна заливка з контрастним текстом; soft — приглушений фон із
// текстом кольору тону. Компонент із тоном задає й колір тексту всередині
// (--fill-fg), тож вкладений текст без власного тону його успадковує.
const v = (name) => `var(${name})`;
export const toneFillStyle = (tone, emphasis) => (emphasis === 'strong'
    ? {
        '--fill-bg': v(toneVar(tone, 'solid')),
        '--fill-bg-hover': v(toneVar(tone, 'solidHover')),
        '--fill-bg-pressed': v(toneVar(tone, 'solidPressed')),
        '--fill-fg': v(toneVar(tone, 'onSolid')),
        '--fill-mark': v(toneVar(tone, 'mark')),
    }
    : {
        '--fill-bg': v(toneVar(tone, 'soft')),
        '--fill-bg-hover': v(toneVar(tone, 'softHover')),
        '--fill-bg-pressed': v(toneVar(tone, 'softHover')),
        '--fill-fg': tone === 'neutral' ? v(groupVar('text-primary')) : v(toneVar(tone, 'text')),
        '--fill-mark': v(toneVar(tone, 'mark')),
    });
// Блок-панель без тону (Container за замовчуванням): поверхня панелі, під
// курсором — піднята; ті самі класи .fill, що й у тонів.
export const surfaceFillStyle = () => ({
    '--fill-bg': v(groupVar('surface-panel')),
    '--fill-bg-hover': v(groupVar('surface-panel-hover')),
    '--fill-bg-pressed': v(groupVar('surface-panel-pressed')),
    '--fill-fg': v(groupVar('text-primary')),
});
// Картка-заглушка (.fill + .fillCard): поверхня панелі без тону, смуга зліва —
// кольору скелетона. Нейтральний приглушений фон тону надто близький до
// кольору скелетона, і смужки тексту на ньому зливаються.
export const skeletonCardStyle = () => ({
    '--fill-bg': 'transparent',
    '--fill-fg': v(groupVar('text-primary')),
    '--fill-mark': v(groupVar('skeleton-base')),
});
// Колір тексту: нейтральний strong — основний текст, soft — вторинний; інші
// тони — колір тону як текст (≥ 4.5:1 до поверхні).
export const toneInkStyle = (tone, emphasis) => ({
    '--ink': tone === 'neutral'
        ? v(groupVar(emphasis === 'strong' ? 'text-primary' : 'text-secondary'))
        : v(toneVar(tone, 'text')),
});
// Класи з common.module.css для кожної реакції на курсор — самі класи, а не
// їхні імена: typed CSS modules перевіряють кожен.
export const INTERACTION_CLASSES = {
    none: [cs.fill],
    hover: [cs.fill, cs.fillHover],
    press: [cs.fill, cs.fillPress],
};
