import { jsx as _jsx } from "react/jsx-runtime";
import { useLocation } from 'react-router-dom';
import { RoutePath } from '06_shared/constants/routes';
import { ChipSkeleton } from '06_shared/ui/ChipSkeleton/ChipSkeleton';
// Поточний PNL показується лише на сторінці торгівлі — деінде справжній компонент
// нічого не малює, тож і заглушка теж.
export const Fallback = () => {
    const location = useLocation();
    if (location.pathname !== RoutePath.trading)
        return null;
    return _jsx(ChipSkeleton, { size: 'xs', width: 154 });
};
