// Єдине джерело z-index для всього проєкту. Числа існують лише тут: TS бере
// їх через Z_INDEX, CSS — через змінні --z-index-*, які applyZIndexVars
// виставляє на :root до першого рендера. Голі числа заборонені лінтерами
// (stylelint для CSS, ESLint для інлайн-стилів), проп Overlay — типом.
//
// Шари з приміткою «локально» діють усередині контексту накладання свого
// батька, а не глобально, тож їхнє число порівнюється лише з сусідами.
export const Z_INDEX = {
    // Закрита модалка — під усім, поки грає анімація появи.
    hidden: -1,
    // Локально в .sidebar: фон під висувним меню на мобільному.
    sidebarBackdrop: 1,
    // Локально в .modal: затемнення під вікном модалки.
    modalBackdrop: 1,
    sidebar: 2,
    modal: 5,
    // Фон списку сповіщень мусить бути рівно під самим списком.
    notificationBackdrop: 19,
    notification: 20,
    tooltip: 100,
};
// notificationBackdrop -> --z-index-notification-backdrop
export const zIndexVar = (layer) => `--z-index-${layer.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`)}`;
export function applyZIndexVars(root = document.documentElement) {
    Object.keys(Z_INDEX).forEach((layer) => {
        root.style.setProperty(zIndexVar(layer), String(Z_INDEX[layer]));
    });
}
