import { withAlpha } from './alpha';
import { ACTIVE_UP_DOWN_SCHEME } from './schemes';
import { THEME_GROUPS, toneColors } from './themes';
// Canvas (chart.js) не читає CSS-змінних, тож бере колір рядком звідси — з того
// самого джерела, що й CSS.
// Лінія серії — «мітка» тону (≥ 3:1 до панелі); заливка під нею — та сама мітка
// з прозорістю chartFill.
export const chartSeries = (theme, tone) => {
    const { mark } = toneColors(theme, tone, ACTIVE_UP_DOWN_SCHEME);
    return { borderColor: mark, backgroundColor: withAlpha(mark, 'chartFill') };
};
// Те саме для кількох сегментів (doughnut): тон на сегмент, по порядку.
export const chartSeriesList = (theme, tones) => ({
    borderColor: tones.map((tone) => chartSeries(theme, tone).borderColor),
    backgroundColor: tones.map((tone) => chartSeries(theme, tone).backgroundColor),
});
// Колір тону як текст на полотні графіка (підписи анотацій).
export const chartText = (theme, tone) => toneColors(theme, tone, ACTIVE_UP_DOWN_SCHEME).text;
// Службові елементи графіка: підписи осей, сітка, нульова лінія.
export const chartChrome = (theme) => ({
    axis: THEME_GROUPS[theme]['chart-axis'],
    grid: THEME_GROUPS[theme]['chart-grid'],
    baseline: THEME_GROUPS[theme]['border-strong'],
});
