// Відступи — шкала на кроці 4 (2 — лише для щільних дрібних елементів).
// CSS: --space-*; інлайн-стилі й пропи в TS — SPACE.
export const SPACE = {
    '2xs': 2,
    xs: 4,
    s: 8,
    m: 12,
    l: 16,
    xl: 24,
    '2xl': 32,
};
// Відступ для інлайн-стилю: 'none' — нуль, інакше CSS-змінна кроку.
export const spaceVar = (step) => (step === 'none' ? '0' : `var(--space-${step})`);
