import { jsx as _jsx } from "react/jsx-runtime";
// Порядок каскадних шарів — першим у бандлі, до CSS будь-якого модуля.
import '01_app/styles/layers.css';
import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from '01_app/App';
import { i18nReady } from '06_shared/runtimeConfig/i18n/i18n';
import { applyZIndexVars } from '06_shared/constants/zIndex';
import { applyColorTokens } from '06_shared/constants/colors';
import { applyDesignTokens } from '06_shared/constants/tokens';
import { getThemeFromLS } from '06_shared/utils/getThemeFromLS';
import { preloadCurrentRoute } from '01_app/router/config/routerConfig';
document.body.style.overflow = 'hidden';
const container = document.getElementById('root');
if (!container) {
    throw new Error('Main container not found!');
}
// Змінні --z-index-*, кольорові й дизайн-токени для CSS мають зʼявитися до першого рендера.
applyZIndexVars();
applyColorTokens();
applyDesignTokens();
// Клас теми — до першого рендера, а не з ефекту ThemeProvider: інакше перший
// кадр малюється без жодної кольорової змінної.
document.body.classList.add(getThemeFromLS());
const root = createRoot(container);
// Перший рендер — коли готові переклади й чанк поточної сторінки (вони
// вантажаться паралельно, ~40 мс). Інакше useTranslation призупиняв увесь
// застосунок на кореневій заглушці, а React 19 після показаної заглушки
// відкриває вміст не раніше ніж за 300 мс (FALLBACK_THROTTLE_MS) — текст
// сторінки чекав таймер, а не мережу. Якщо щось не завантажилось, рендеримо
// однаково: коренева Suspense лишається запобіжником.
const ready = Promise.all([i18nReady, preloadCurrentRoute(window.location.pathname)]);
// StrictMode працює лише в dev і подвійним викликом ефектів ловить
// пропущені cleanup — саме так знайшовся витік інтервалу в індикаторі цін.
ready.catch(() => undefined).finally(() => {
    // Тема плейсхолдера з index.html більше не потрібна: фон дає .app.
    delete document.documentElement.dataset.bootTheme;
    root.render(_jsx(StrictMode, { children: _jsx(App, {}) }));
});
