// Прозорість — одна шкала для CSS і canvas, за ролями, а не «на око».
// Результат — 8-значний hex (#rrggbbaa): однаково читається CSS і chart.js.
export const ALPHA = {
    clear: 0, // повністю прозорий — краї відблиску скелетона, доріжка скролбару
    tint: 0.16, // приглушений фон тону (emphasis soft): бейдж, рядок, сповіщення
    tintHover: 0.2, // той самий фон під курсором
    chartFill: 0.14, // заливка під лінією чи сегментом графіка
    selection: 0.3, // виділення тексту
    overlayDark: 0.72, // затемнення під модалкою в темній темі
    overlayLight: 0.36, // затемнення під модалкою у світлій темі
};
export const withAlpha = (hex, alpha) => `${hex}${Math.round(ALPHA[alpha] * 255).toString(16).padStart(2, '0')}`;
// Накладання кольору з прозорістю на непрозорий фон — для перевірки контрасту
// тексту на tint-фоні (що бачить око, а не що записано в CSS).
export function composite(overHex8, underHex) {
    const channel = (hex, i) => parseInt(hex.slice(1 + i * 2, 3 + i * 2), 16);
    const alpha = overHex8.length === 9 ? parseInt(overHex8.slice(7, 9), 16) / 255 : 1;
    const mix = (i) => Math.round(channel(overHex8, i) * alpha + channel(underHex, i) * (1 - alpha));
    return `#${[0, 1, 2].map((i) => mix(i).toString(16).padStart(2, '0')).join('')}`;
}
