import { useContext } from 'react';
import { LS_OPENED_MENU_KEY, MenuContext, } from '06_shared/contexts/MenuContext';
export function useMenu() {
    const { menu, setMenu } = useContext(MenuContext);
    const toggleMenu = () => {
        setMenu?.(!menu);
        localStorage.setItem(LS_OPENED_MENU_KEY, String(!menu));
    };
    return {
        menu: !!menu,
        toggleMenu,
    };
}
