import { Theme } from '06_shared/contexts/ThemeContext';
import { SCALES, WHITE } from './palette';
import { withAlpha } from './alpha';
import { ACTIVE_UP_DOWN_SCHEME } from './schemes';
import { resolveTone } from './tones';
// Рівень 3 — теми: які кроки палітри грають які ролі в кожній темі. Кожне
// значення тут вибране явно й перевіряється тестом контрасту WCAG
// (colors.test.ts): текст ≥ 4.5:1, рамки й лінії ≥ 3:1.
const G = SCALES.graphite;
const S = SCALES.sand;
const scale = (family) => SCALES[family];
// Хроматичне сімейство в темній темі: заливка яскрава, текст на ній темний
// (на всіх цих відтінках темний дає вищий контраст, ніж білий). З темним текстом
// hover і pressed світлішають: темніша заливка з'їла б контраст.
const darkFamily = (family, solid, text = solid) => ({
    solid: scale(family)[solid],
    solidHover: scale(family)[solid - 100],
    solidPressed: scale(family)[solid - 100],
    onSolid: G[950],
    text: scale(family)[text],
    mark: scale(family)[solid],
});
// У світлій темі заливка глибша; текст на ній — білий або темний, що вищий.
// З білим текстом hover/pressed темнішають, з темним — світлішають.
const lightFamily = (family, solid, onSolid, text, mark = solid, hover = solid + 100, pressed = solid + 200) => ({
    solid: scale(family)[solid],
    solidHover: scale(family)[hover],
    solidPressed: scale(family)[pressed],
    onSolid,
    text: scale(family)[text],
    mark: scale(family)[mark],
});
const FAMILY_TONES = {
    [Theme.DARK]: {
        gold: darkFamily('gold', 300),
        azure: darkFamily('azure', 500),
        // Ріст і падіння: заливка глибша з білим текстом — на насиченому
        // зеленому й червоному темний текст формально контрастний, але читається
        // гірше. Лінії, мітки й кольоровий текст лишаються яскравими.
        emerald: lightFamily('emerald', 650, WHITE, 400, 400, 700, 750),
        crimson: lightFamily('crimson', 600, WHITE, 400, 500, 700, 800),
        amber: darkFamily('amber', 400),
        blue: darkFamily('blue', 500, 400),
        violet: darkFamily('violet', 400),
    },
    [Theme.LIGHT]: {
        gold: lightFamily('gold', 400, S[900], 700),
        azure: lightFamily('azure', 650, WHITE, 750, 600, 700, 800),
        emerald: lightFamily('emerald', 650, WHITE, 750, 600, 700, 750),
        crimson: lightFamily('crimson', 600, WHITE, 750),
        amber: lightFamily('amber', 500, S[900], 750, 600, 400, 400),
        blue: lightFamily('blue', 700, WHITE, 750),
        violet: lightFamily('violet', 700, WHITE, 750, 600),
    },
};
// Бренд: золото в темній темі, лазур у світлій (рішення продукту).
const BRAND_FAMILY = {
    [Theme.DARK]: 'gold',
    [Theme.LIGHT]: 'azure',
};
// Ролі, що не є сімейством: нейтральний тон (чип, бейдж; приглушений фон —
// піднята поверхня, а не прозорість), обʼєм і лінія входу на графіку. Блок-
// панель — не тон, а поверхня: surfaceFillStyle у styles.ts.
const ROLE_TONES = {
    [Theme.DARK]: {
        neutral: {
            solid: G[800], solidHover: G[700], solidPressed: G[600], onSolid: G[100],
            soft: G[850], softHover: G[800], text: G[100], mark: G[400],
        },
        // Обʼєм і вхід — лише для графіків: заливки з текстом у них немає.
        volume: {
            solid: G[700], solidHover: G[600], solidPressed: G[600], onSolid: G[100],
            text: G[300], mark: G[500],
        },
        entry: {
            solid: G[100], solidHover: G[50], solidPressed: G[200], onSolid: G[950],
            text: G[100], mark: G[100],
        },
    },
    [Theme.LIGHT]: {
        neutral: {
            solid: S[200], solidHover: S[300], solidPressed: S[400], onSolid: S[900],
            soft: S[150], softHover: S[200], text: S[900], mark: S[600],
        },
        volume: {
            solid: S[300], solidHover: S[400], solidPressed: S[400], onSolid: S[900],
            text: S[700], mark: S[500],
        },
        entry: {
            solid: S[900], solidHover: S[800], solidPressed: S[950], onSolid: S[50],
            text: S[900], mark: S[900],
        },
    },
};
const withSoft = (base) => ({
    ...base,
    // Приглушений фон — від мітки, а не від заливки: мітка яскравіша, тож
    // фон картки чи чипа виразніший при тій самій прозорості.
    soft: base.soft ?? withAlpha(base.mark, 'tint'),
    softHover: base.softHover ?? withAlpha(base.mark, 'tintHover'),
});
export function toneColors(theme, tone, scheme = ACTIVE_UP_DOWN_SCHEME) {
    const resolved = resolveTone(tone, scheme);
    if ('role' in resolved) {
        if (resolved.role === 'brand')
            return withSoft(FAMILY_TONES[theme][BRAND_FAMILY[theme]]);
        return withSoft(ROLE_TONES[theme][resolved.role]);
    }
    const { family } = resolved;
    if (family === 'graphite' || family === 'sand')
        return withSoft(ROLE_TONES[theme].neutral);
    return withSoft(FAMILY_TONES[theme][family]);
}
// Іменовані ролі інтерфейсу. Ключ — хвіст CSS-змінної: 'surface-panel' ->
// --color-surface-panel.
const brand = (theme) => FAMILY_TONES[theme][BRAND_FAMILY[theme]];
