        'input-bg': G[950],
        'input-border': G[800],
        'input-border-hover': G[500],
        'input-placeholder': G[500],
        'button-secondary-bg': G[850],
        'button-secondary-bg-hover': G[800],
        'button-secondary-bg-pressed': G[700],
        'button-secondary-fg': G[100],
        'button-secondary-border': G[800],
