export function createDynamicMiddleware() {
    const raw = [];
    const handlers = [];
    let storeRef = null;
    const middleware = (store) => {
        storeRef = store;
        handlers.length = 0;
        for (const mw of raw) {
            handlers.push(mw(store));
        }
        return (next) => (action) => {
            let idx = 0;
            // Redux 5 типізує ланцюг middleware через unknown, тож сигнатури
            // збігаються напряму й приведення типу більше не потрібне.
            const invoke = (act) => {
                if (idx >= handlers.length) {
                    return next(act);
                }
                const cur = handlers[idx++];
                return cur(invoke)(act);
            };
            return invoke(action);
        };
    };
    return {
        middleware,
        add(mw) {
            if (raw.includes(mw))
                return;
            raw.push(mw);
            if (storeRef) {
                handlers.push(mw(storeRef));
            }
        },
        remove(mw) {
            const i = raw.indexOf(mw);
            if (i === -1)
                return;
            raw.splice(i, 1);
            if (i < handlers.length) {
                handlers.splice(i, 1);
            }
        },
    };
}
