import { DEFAULT_THEME, Theme } from '06_shared/contexts/ThemeContext';
import { ACTIVE_UP_DOWN_SCHEME } from './schemes';
import { TONE_NAMES } from './tones';
import { THEME_GROUPS, toneColors } from './themes';
const kebab = (name) => name.replace(/[A-Z]/g, (char) => `-${char.toLowerCase()}`);
// takeProfit, solidHover -> --color-take-profit-solid-hover
export const toneVar = (tone, role) => `--color-${kebab(tone)}-${kebab(role)}`;
// 'surface-panel' -> --color-surface-panel
export const groupVar = (name) => `--color-${name}`;
export const THEMES = [Theme.DARK, Theme.LIGHT];
export function themeColorVars(theme, scheme = ACTIVE_UP_DOWN_SCHEME) {
    const vars = {};
    TONE_NAMES.forEach((tone) => {
        const colors = toneColors(theme, tone, scheme);
        Object.keys(colors).forEach((role) => {
            vars[toneVar(tone, role)] = colors[role];
        });
    });
    Object.entries(THEME_GROUPS[theme]).forEach(([name, value]) => {
        vars[groupVar(name)] = value;
    });
    return vars;
}
// color-scheme — щоб нативні елементи (скролбар, автозаповнення полів,
// календар, чекбокси) малювались у тон теми, а не завжди світлими.
const COLOR_SCHEME = {
    [Theme.DARK]: 'dark',
    [Theme.LIGHT]: 'light',
};
const block = (selector, theme, vars) => {
    const declarations = Object.entries(vars).map(([name, value]) => `${name}:${value};`).join('');
    return `${selector}{color-scheme:${COLOR_SCHEME[theme]};${declarations}}`;
};
export function buildColorTokensCss(scheme = ACTIVE_UP_DOWN_SCHEME) {
    return [
        block(':root', DEFAULT_THEME, themeColorVars(DEFAULT_THEME, scheme)),
        ...THEMES.map((theme) => block(`.${theme}`, theme, themeColorVars(theme, scheme))),
    ].join('\n');
}
export const COLOR_TOKENS_STYLE_ID = 'color-tokens';
export function applyColorTokens(doc = document, scheme = ACTIVE_UP_DOWN_SCHEME) {
    let style = doc.getElementById(COLOR_TOKENS_STYLE_ID);
    if (!style) {
        style = doc.createElement('style');
        style.id = COLOR_TOKENS_STYLE_ID;
        doc.head.appendChild(style);
    }
    style.textContent = buildColorTokensCss(scheme);
}
