import { lazy } from 'react';
// React.lazy, чий модуль можна почати вантажити заздалегідь (preload), а
// вже завантажений — віддати синхронно. Синхронний thenable React.lazy
// розвʼязує одразу, без suspend: сторінка не показує заглушку, а отже не
// потрапляє під тротлінг React 19 (FALLBACK_THROTTLE_MS — вміст після
// щойно показаної заглушки відкривається не раніше ніж за 300 мс).
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export function lazyWithPreload(load) {
    let loaded;
    let pending;
    const preload = () => {
        pending ?? (pending = load().then((module) => {
            loaded = module;
            return module;
        }));
        return pending;
    };
    const Component = lazy(() => {
        if (loaded) {
            const module = loaded;
            // Синхронний thenable: React одразу бачить модуль і не призупиняє рендер.
            const ready = { then: (resolve) => resolve(module) };
            return ready;
        }
        return preload();
    });
    return Object.assign(Component, { preload });
}
