import { useContext } from 'react';
import { DEFAULT_THEME, Theme, ThemeContext, } from '06_shared/contexts/ThemeContext';
import { LS_SELECTED_THEME_KEY } from '06_shared/constants/localStorage';
export function useTheme() {
    const { theme, setTheme } = useContext(ThemeContext);
    const toggleTheme = () => {
        if (!setTheme) {
            return;
        }
        const newTheme = theme === Theme.DARK
            ? Theme.LIGHT
            : Theme.DARK;
        setTheme(newTheme);
        localStorage.setItem(LS_SELECTED_THEME_KEY, newTheme);
    };
    return {
        theme: theme || DEFAULT_THEME,
        toggleTheme,
    };
}
