import { combineReducers, configureStore } from '@reduxjs/toolkit';
import { createDynamicMiddleware } from './middlewareManager';
// Тип вказано явно, з приведенням: combineReducers виводить стан зі
// значень карти, а тут усі ключі опціональні, бо стор стартує порожнім
// і наповнюється в рантаймі. Приведення чесно відображає цей контракт.
function createReducer(asyncReducers) {
    // Для порожньої карти віддаємо тривіальний редʼюсер замість виклику
    // combineReducers: для Redux порожня карта — помилка конфігурації, а
    // тут це штатний старт, і його console.error валив аудит консолі.
    if (Object.keys(asyncReducers).length === 0) {
        return ((state = {}) => state);
    }
    return combineReducers({
        ...asyncReducers,
    });
}
export class ReducerManager {
    constructor(initialReducers, initialState) {
        this.dynamicMiddleware = createDynamicMiddleware();
        this.reducers = initialReducers;
        this.store = configureStore({
            reducer: createReducer(this.reducers),
            preloadedState: initialState,
            // RTK 2 вимагає саме Tuple, а не звичайний масив: спред у
            // Middleware[] губив цей тип. .concat дає Tuple штатно.
            middleware: (getDefaultMiddleware) => getDefaultMiddleware({
                serializableCheck: false,
            }).concat(this.dynamicMiddleware.middleware)
        });
    }
    configureStore(initialReducers, initialState) {
        const oldState = this.store.getState();
        this.reducers = initialReducers;
        this.store = configureStore({
            reducer: createReducer(this.reducers),
            preloadedState: { ...oldState, ...initialState },
            // RTK 2 вимагає саме Tuple, а не звичайний масив: спред у
            // Middleware[] губив цей тип. .concat дає Tuple штатно.
            middleware: (getDefaultMiddleware) => getDefaultMiddleware({
                serializableCheck: false,
            }).concat(this.dynamicMiddleware.middleware)
        });
    }
    getStore() {
        return this.store;
    }
    getReducerMap() {
        return this.reducers;
    }
    add(key, reducer) {
        if (this.reducers[key])
            return;
        this.reducers[key] = reducer;
        this.store.replaceReducer(createReducer(this.reducers));
    }
    remove(key) {
        if (!this.reducers[key])
            return;
        delete this.reducers[key];
        this.store.replaceReducer(createReducer(this.reducers));
    }
    addMiddleware(mw) {
        this.dynamicMiddleware.add(mw);
    }
    removeMiddleware(mw) {
        this.dynamicMiddleware.remove(mw);
    }
}
