import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import Backend from 'i18next-http-backend';
import LanguageDetector from 'i18next-browser-languagedetector';
// Проміс ініціалізації: розвʼязується, коли основний простір перекладів
// завантажено. src/index.tsx чекає на нього перед першим рендером.
export const i18nReady = i18n
    .use(Backend) // use - setup plugins
    .use(LanguageDetector)
    .use(initReactI18next)
    .init({
    fallbackLng: 'en', //default language
    // Лише мови, для яких є папки в public/locales: мова браузера з регіоном
    // ('uk-UA', 'en-US') зводиться до них, а непідтримувана ('de') — одразу на
    // fallbackLng, без запитів за перекладами, яких немає. Коди — справжні
    // BCP-47 (uk, а не ua): Intl і <html lang> приймають їх як є.
    supportedLngs: ['en', 'uk'],
    // LanguageDetector віддає мову з регіоном ('en-US'), а папок локалей
    // рівно дві. Без цього кожне завантаження давало по три 404 у консолі,
    // перш ніж i18next відкотиться на 'en'.
    load: 'languageOnly',
    debug: __IS_DEV__, // for debug mode
    interpolation: {
        escapeValue: false, // not needed for react as it escapes by default
    },
    backend: {
        loadPath: '/locales/{{lng}}/{{ns}}.json', //path for loads translation
    },
});
// <html lang> — за мовою інтерфейсу: скринрідер читає текст правильною
// вимовою, пошуковик бачить мову сторінки. В index.html лише початкове 'en'.
i18n.on('languageChanged', () => {
    document.documentElement.lang = i18n.resolvedLanguage ?? i18n.language;
});
export default i18n;
