import * as Sentry from '@sentry/react';
// Порожній DSN — штатна поведінка SDK, а не милиця: Sentry.init просто
// нічого нікуди не надсилає, доки адресу не задано на збірці.
if (__SENTRY_DSN__) {
    Sentry.init({
        dsn: __SENTRY_DSN__,
        environment: __IS_DEV__ ? 'development' : 'production',
        // SDK 11 за замовчуванням збирає більше, ніж 10: cookies, тіла HTTP-запитів
        // і відповідей, дані користувача. У торговому клієнті в тілах їдуть ордери
        // й токени, тож лишаємо обсяг, як був у 10 без sendDefaultPii.
        dataCollection: {
            userInfo: false,
            cookies: false,
            httpBodies: [],
        },
    });
}
// Єдина точка репортингу помилок: справжня відправка вмикається
// налаштуванням оточення, без правки коду.
export const reportError = (error, errorInfo) => {
    console.error(error, errorInfo);
    if (!__SENTRY_DSN__)
        return;
    Sentry.captureException(error, {
        contexts: errorInfo ? { react: { componentStack: errorInfo.componentStack } } : undefined,
    });
};
