import i18n from './i18n';
// Простір перекладів сторінки вантажиться паралельно з її чанком, а не
// після: інакше компонент рендериться, викликає useTranslation('ns') і лише
// тоді йде по JSON — ще один крок у ланцюжку перед першим відмальовуванням.
export const withNamespaces = (load, namespaces) => () => Promise.all([load(), i18n.loadNamespaces(namespaces)]).then(([module]) => module);
